import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { ClaimView, LateTerms, cents, latePeriods, money } from './claims';
import { Grade } from './people';

export interface RateView {
  grade: Grade;
  /** The percent with two decimals, e.g. "12.50". */
  pct: string;
  /** The date (yyyy-mm-dd) the rate applies from; null when it applies from the beginning of time. */
  from: string | null;
}

/** A rate as set through the form; a null from-date applies from the beginning of time. */
export interface RateForm {
  pct: string;
  from: string | null;
}

/** A from-date as a rate takes it: yyyy-mm-dd. */
export const FROM_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * The rate a grade has in force on a date (yyyy-mm-dd): of its rates with no from-date or one on or
 * before the date, the one with the latest; null when the date is before every rate of the grade.
 */
export function rateOn(rates: RateView[], grade: Grade, date: string): string | null {
  let best: RateView | null = null;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === null || (r.from !== null && (best.from === null || r.from > best.from))) best = r;
  }
  return best?.pct ?? null;
}

/** Whether two rates are for the same grade and from-date, so one replaces the other. */
export function sameSlot(a: RateView, b: RateView): boolean {
  return a.grade === b.grade && a.from === b.from;
}

/** A percent as a rate takes it: 0.00 or more, with up to two decimals. */
export const PERCENT = /^\d{1,3}(\.\d{1,2})?$/;

/** Shown in place of a due when the grade has no rate. */
export const NO_RATE = 'n/a';

/**
 * What is due on an amount in whole cents at a rate (a two-decimal percent): the amount times the
 * rate divided by 100, rounded half to even to whole cents. Worked in integers so it is exact.
 */
export function dueCents(amountCents: number, pct: string, times = 1): number {
  const [whole, frac = ''] = pct.split('.');
  const basisPoints = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
  const exact = BigInt(amountCents) * basisPoints * BigInt(times);
  const quotient = exact / 10000n;
  const remainder = exact % 10000n;
  const up = remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n);
  return Number(up ? quotient + 1n : quotient);
}

/** What is due on an amount in whole cents at a rate, shown with two decimals; n/a with no rate in force. */
export function due(amountCents: number, pct: string | null): string {
  return pct === null ? NO_RATE : money(dueCents(amountCents, pct));
}

/**
 * A claim's due in whole cents: the due fixed when it was settled (its late charge frozen in), or
 * else its figure — the one its person's last statement bound it to, or else its amount at the rate
 * the grade has in force on the claim's date raised to the sheet's floor (in whole cents) when below
 * it — with the late charge on top: the late percent of the figure for every full 30 days the claim
 * is overdue, rounded half to even. The charge is never bound by a statement. Null when there is no
 * figure.
 */
export function claimDueCents(
  claim: ClaimView,
  rates: RateView[],
  grade: Grade,
  floorCents: number,
  late: LateTerms,
): number | null {
  if (claim.settledDue !== null) return cents(claim.settledDue);
  let figure: number | null;
  if (claim.stated) {
    figure = claim.statedDue === null ? null : cents(claim.statedDue);
  } else {
    const pct = rateOn(rates, grade, claim.date);
    figure = pct === null ? null : Math.max(dueCents(cents(claim.amount), pct), floorCents);
  }
  return figure === null ? null : figure + dueCents(figure, late.pct, latePeriods(claim, late));
}

// The rates for the grades on a sheet, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class RatesApi {
  private readonly http = inject(HttpClient);

  /** The sheet's rates, each grade's by from-date; a grade with no rate is not listed. */
  list(sheet: string): Promise<RateView[]> {
    return firstValueFrom(this.http.get<RateView[]>(this.url(sheet)));
  }

  /** Set a grade's rate from a date, replacing any it had from that date. */
  set(sheet: string, grade: Grade, form: RateForm): Promise<RateView> {
    return firstValueFrom(this.http.put<RateView>(`${this.url(sheet)}/${grade}`, form));
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/rates`;
  }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: what each person has claimed and their due-total,
 * and the sheet's claimed-total and due-total. A change takes them before it writes and has them
 * audited after its own records, so every figure it moves is recorded.
 */
@Service
public class Rollups {

    /** Shown in place of a due-total when the grade has no rate. */
    private static final String NO_RATE = "n/a";

    /** A person's figures: what they have claimed and their due-total (null when n/a). */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {

        boolean sameAs(Figures other) {
            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal);
        }
    }

    /** The sheet's figures: each person's by id, in the order they were added, and the sheet's totals. */
    public record Rollup(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Dues dues;
    private final Audit audit;

    public Rollups(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            Dues dues, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.dues = dues;
        this.audit = audit;
    }

    /** The sheet's figures as they stand now in the current transaction. */
    public Rollup take(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus().counts()) {
                byPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        BigDecimal dueTotal = zero();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counting = byPerson.getOrDefault(person.getId(), List.of()).stream()
                    .filter(claim -> person.countsLive(claim.getStatus()))
                    .toList();
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            boolean figured = false;
            for (Claim claim : counting) {
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()));
                if (figure != null) {
                    due = due.add(figure);
                    figured = true;
                }
            }
            // As on the screen: n/a when the grade in force today has no rate, unless a claim has a
            // figure (a fixed one, or one at the grade in force on its own date).
            boolean rated = today != null && rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
            if (!rated && !figured) {
                due = null;
            }
            figures.put(person.getId(), new Figures(person.getName(), claimed, due));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) {
                dueTotal = dueTotal.add(due);
            }
        }
        return new Rollup(figures, claimedTotal, dueTotal);
    }

    /**
     * Record, once the change commits, one ROLLUP line per person whose figures moved since
     * {@code before} (a person new since then counts as moved), then a TOTALS line when the sheet's
     * totals moved.
     */
    public void audit(String sheetId, String user, Rollup before) {
        Rollup after = take(sheetId);
        after.people().forEach((id, figures) -> {
            if (!figures.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed().toPlainString() + " due-total=" + shown(figures.dueTotal()));
            }
        });
        if (!same(after.claimedTotal(), before.claimedTotal()) || !same(after.dueTotal(), before.dueTotal())) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user
                    + " claimed-total=" + after.claimedTotal().toPlainString()
                    + " due-total=" + after.dueTotal().toPlainString());
        }
    }

    /** Whether two figures are the same amount, or both n/a. */
    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null ? b == null : b != null && a.compareTo(b) == 0;
    }

    private static String shown(BigDecimal due) {
        return due != null ? due.toPlainString() : NO_RATE;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }
}
